#pragma once

namespace hub {
// Generic profile transport and scheduling only. Device adapters live in plugins.
inline std::wstring pluginProfilesBootstrap(JsonObject state){auto code=std::wstring(LR"PROFILESDK(
<script>(()=>{
const taskExtensions=[];const pending=new Map();let sequence=0,busy=false,lastRequest='';
function call(operation,body={}){return new Promise((resolve,reject)=>{const token='profile-'+(++sequence)+'-'+Date.now();const timer=setTimeout(()=>{pending.delete(token);reject(Error('配置接口响应超时'));},15000);pending.set(token,{resolve,reject,timer});chrome.webview.postMessage({type:'hhub.profiles',token,body:{operation,...body}});});}
chrome.webview.addEventListener('message',e=>{const m=e.data;if(m.type!=='hhub.profiles.result')return;const p=pending.get(m.token);if(!p)return;clearTimeout(p.timer);pending.delete(m.token);m.error?p.reject(Error(m.error)):p.resolve(m.result);});
function feedback(ok,message){window.dispatchEvent(new CustomEvent('hhub-profiles-feedback',{detail:{ok,message}}));if(!window.hhubProfileWorker)chrome.webview.postMessage({type:'hhub.profiles.feedback',ok,message});}
function adapter(){const a=window.hhubProfileAdapter;if(!a?.capture||!a?.apply)throw Error('此插件尚未提供配置接口');return a;}
async function save(profile){if(!profile)throw Error('先在场景页为该外设新建配置');const state=await call('state');const p=(state.profiles||[]).find(p=>p.id===profile);if(!p)throw Error('配置不存在');await call('capture',{profile,payload:await adapter().capture(p)});lastRequest='';}
window.HhubProfiles={call,save,activeProfile:''};let saveTimer;
window.HhubProfiles.changed=()=>{if(!window.hhubCompactProfiles||!window.HhubProfiles.activeProfile)return;clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{if(busy){window.HhubProfiles.changed();return;}busy=true;try{await save(window.HhubProfiles.activeProfile);}catch(e){feedback(false,e.message);}finally{busy=false;}},1200);};
window.addEventListener('DOMContentLoaded',()=>{
 chrome.webview.addEventListener('message',async e=>{if(e.data.type!=='hhub.profiles.select'||busy)return;busy=true;try{const state=await call('state');const p=(state.profiles||[]).find(p=>p.id===e.data.profile);if(!p)throw Error('配置不存在');const a=adapter();if(p.payload){await call('validate',{profile:p.id});if(await a.apply(p.payload)!==true)throw Error('配置回读未确认');}else await call('capture',{profile:p.id,payload:await a.capture(p)});await call('manual',{profile:p.id});window.HhubProfiles.activeProfile=p.id;feedback(true,'配置已确认');}catch(e){feedback(false,e.message);}finally{busy=false;}});
 setInterval(async()=>{if(busy)return;busy=true;try{const state=await call('state');for(const handler of taskExtensions)if(await handler(state))return;window.dispatchEvent(new CustomEvent('hhub-profiles-state',{detail:state}));const task=(state.pending||[]).find(x=>x.state==='waitingPlugin'&&x.requestId!==lastRequest);if(task&&window.hhubProfileAdapter){const p=(state.profiles||[]).find(p=>p.id===task.profile);if(p?.payload){lastRequest=task.requestId;try{const a=adapter();if(window.hhubProfileWorker&&a.connect)await a.connect(p.payload);await call('validate',{profile:p.id});if(await a.apply(p.payload)!==true)throw Error('设备未通过配置回读');await call('ack',{profile:p.id,requestId:task.requestId,confirmed:true});feedback(true,'场景配置已应用并回读确认');}catch(e){await call('ack',{profile:p.id,requestId:task.requestId,confirmed:false,error:e.message});feedback(false,e.message);}}}}catch(e){feedback(false,e.message);}finally{busy=false;}},1500);
});})();
</script>
)PROFILESDK");for(auto const& value:state.GetNamedArray(L"plugins",JsonArray{})){auto plugin=value.GetObject();if(!flag(plugin,L"installed")||flag(plugin,L"forceStopped")||str(plugin,L"mode")==L"disabled")continue;auto extensions=plugin.GetNamedArray(L"workerExtensions",JsonArray{});if(!extensions.Size())continue;verifyNativeAssets(str(plugin,L"id"));for(auto const& extension:extensions){auto path=std::wstring(extension.GetString());auto assets=nativeAssetDefinitions(str(plugin,L"id"));if(!validAssetName(path)||std::filesystem::path(path).extension()!=L".js"||std::none_of(assets.begin(),assets.end(),[&](auto const& asset){return asset.name==path;}))throw hresult_invalid_argument(L"插件扩展未声明在组件包中");code.insert(code.find(L"window.addEventListener('DOMContentLoaded'"),read(dataDir()/L"native-components"/str(plugin,L"id")/path));}}return code;}
}
